import{_ as a,H as i,f as t,i as e}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"28 | 视觉：避免发生布局偏移影响用户交互","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是 CLS？","slug":"什么是-cls","link":"#什么是-cls","children":[{"level":3,"title":"深入理解 CLS","slug":"深入理解-cls","link":"#深入理解-cls","children":[]}]},{"level":2,"title":"LayoutShiftScore = impactfraction ∗distancefraction","slug":"layoutshiftscore-impactfraction-∗distancefraction","link":"#layoutshiftscore-impactfraction-∗distancefraction","children":[]},{"level":2,"title":"CLS = SUM(LS","slug":"cls-sum-ls","link":"#cls-sum-ls","children":[{"level":3,"title":"分数与视觉的关系","slug":"分数与视觉的关系","link":"#分数与视觉的关系","children":[]}]},{"level":2,"title":"优化建议","slug":"优化建议","link":"#优化建议","children":[{"level":3,"title":"图片尺寸问题","slug":"图片尺寸问题","link":"#图片尺寸问题","children":[]},{"level":3,"title":"动态内容","slug":"动态内容","link":"#动态内容","children":[]},{"level":3,"title":"动画问题","slug":"动画问题","link":"#动画问题","children":[]},{"level":3,"title":"字体问题","slug":"字体问题","link":"#字体问题","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"前端全链路优化实战课/28｜视觉：避免发生布局偏移影响用户交互.md","filePath":"前端全链路优化实战课/28｜视觉：避免发生布局偏移影响用户交互.md","lastUpdated":1795541984000}'),n={name:"前端全链路优化实战课/28｜视觉：避免发生布局偏移影响用户交互.md"};function p(l,s,h,o,c,r){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="_28-视觉-避免发生布局偏移影响用户交互" tabindex="-1">28 | 视觉：避免发生布局偏移影响用户交互 <a class="header-anchor" href="#_28-视觉-避免发生布局偏移影响用户交互" aria-label="Permalink to &quot;28 | 视觉：避免发生布局偏移影响用户交互&quot;">​</a></h1><p>你好，我是三桥。</p><p>上节课，我们通过实例解决了视口中图片加载的问题，经过几轮优化，图片在视口中的显示速度得到了提升。</p><p>然而，在优化之前，视口中的图片加载还存在一个问题，那就是页面视觉稳定性都不太好。下图是上节课优化过程的时序图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/1.png" alt=""></a></p><p>上面四张时序图显示，图 1 是优化前的官网加载时序图，报告显示有严重的布局偏移问题，得分是 0.7450。</p><p>这是因为图 1 中的图片是通过后台读取的富文本内容，而且没有设置图片的宽高，这就导致浏览器没有给图片预留布局空间。直到当图片加载时，底部内容才会被移出视口。</p><p>其它时序图没有出现布局偏移，因为所有图片都预设了宽高属性。</p><p>也就是说，视口中的元素，无论是图片还是文本，如果设置了宽高，正常情况下是不会有布局偏移的。</p><h2 id="什么是-cls" tabindex="-1">什么是 CLS？ <a class="header-anchor" href="#什么是-cls" aria-label="Permalink to &quot;什么是 CLS？&quot;">​</a></h2><p>不知道你之前有没有遇到过下面的几种情况。</p><ul><li><p>阅读一篇新闻文章时，页面顶部的广告突然弹出，导致所有内容向下移动。这种被中断的感觉让人十分沮丧。</p></li><li><p>通过手机 H5 页面购物时，购物车中有几件商品。你想更新商品数量，然后继续购物。但是你点击编辑后，页面布局改变了，手指误触了“删除按钮”而不是 “+1” 按钮。视觉位置突变，让使用体验非常糟糕。</p></li><li><p>填写表单时，选择一个选项之后导致页面内容发生变化，不知道下一步该怎么填写，很迷茫。</p></li></ul><p>可以说，布局偏移在网页加载期间非常常见，因为浏览器需要获取所有必要的资源来显示视口可见的内容，而且初始加载后也可能会发生布局偏移。</p><p>为了提供高质量的网页效果，避免这种糟糕的用户体验的网页出现在搜索结果中，谷歌搜索引擎提出了视觉稳定性指标，作为核心网页指标。</p><h3 id="深入理解-cls" tabindex="-1">深入理解 CLS <a class="header-anchor" href="#深入理解-cls" aria-label="Permalink to &quot;深入理解 CLS&quot;">​</a></h3><p>累积布局偏移（Cumulative Layout Shift，简称 CLS）是一个网页指标，用于衡量在网页的整个生命周期内所有意外布局偏移的总分。</p><p>从基本概念来看，CLS 有四个主要特点。</p><p>第一，涵盖网页的整个生命周期。无论是在加载过程中，还是用户交互过程中，都有可能发生CLS。</p><p>第二，网页布局偏移可能发生一次或多次。</p><p>第三，最后的偏移分数是所有布局偏移分数的总和。其中，布局偏移分数由影响比例和距离分数两个因素决定。计算公式为：</p><h2 id="layoutshiftscore-impactfraction-∗distancefraction" tabindex="-1">LayoutShiftScore = impactfraction ∗distancefraction <a class="header-anchor" href="#layoutshiftscore-impactfraction-∗distancefraction" aria-label="Permalink to &quot;LayoutShiftScore = impactfraction ∗distancefraction&quot;">​</a></h2><p>而偏移分数的总和即为：</p><h2 id="cls-sum-ls" tabindex="-1">CLS = SUM(LS <a class="header-anchor" href="#cls-sum-ls" aria-label="Permalink to &quot;CLS = SUM(LS&quot;">​</a></h2><ul><li>​core1, LS​core2, LS​core3, … …)SSS</li></ul><p>第四，CLS 值是一个分数，而不是时间值。</p><p>第五，只有在视口内的可见元素在渲染两帧之间相对于初始位置发生改变，才会被认为发生了布局偏移。</p><p>谷歌为 CLS 指标设定了一套衡量标准。分数低于 0.1 或没有这个值，就认为没有用户体验问题。如果分数小于 0.25，那么页面就有改进的空间。当分数大于 0.25 时，就认为存在布局偏移问题，需要重点关注。</p><p>下图清晰地展示了不同分数区间的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/2.png" alt=""></a></p><p>有了这个得分，我们就可以在前端全链路方案中，设置一个阈值，通过这个阈值可以提醒前端同学用户的实际情况，从而初步判断哪个页面可能会影响用户体验。</p><p>虽然这个分数只是一个参考值，但在实际分析用户体验问题时，我们还需要通过开发者工具进行分析这个值，再下结论。接下来，我们将使用上一节课的例子来进一步解释 CLS 分数和实际的布局偏移效果。</p><h3 id="分数与视觉的关系" tabindex="-1">分数与视觉的关系 <a class="header-anchor" href="#分数与视觉的关系" aria-label="Permalink to &quot;分数与视觉的关系&quot;">​</a></h3><p>我们再看一下网页加载时页面布局的变化效果，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/3.png" alt=""></a></p><p>这张动图里，布局偏移出现了两次。</p><p>第一次布局偏移发生在头部和底部内容渲染完成后，底部区域突然向上移动，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/4.png" alt=""></a></p><p>在整个偏移过程中，红色透明底在视口区域的占比超过 67%，说明影响比例为 0.67。移动距离大约为 106 像素，约占屏幕比例的 12.5%。因此，通过公式计算得出的分数为 0.08417。</p><p>然后，我们来看第二次布局偏移，这次的位置偏移更严重，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%85%A8%E9%93%BE%E8%B7%AF%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98%E8%AF%BE/images/28/5.png" alt=""></a></p><p>从图中可以看出，底部区域已完全被移出屏幕视口。在偏移过程中，红色透明底在视口区域占比 78.4%，所以布局偏移值为 0.784。此次布局偏移得分是 0.7450，影响比例接近于 1。</p><p>最后，CLS 累积偏移值是 0.8291 分，是由两次布局偏移分数相加得出的。</p><p>因此，我们可以得出这样一个结论：元素偏移的位置距离越远，布局偏移值就越大；影响视口面积越大，其影响比例也就越高，布局偏移值也就越大。</p><p>接下来，我们继续探讨如何避免这些问题。</p><h2 id="优化建议" tabindex="-1">优化建议 <a class="header-anchor" href="#优化建议" aria-label="Permalink to &quot;优化建议&quot;">​</a></h2><p>想要避免这个问题，我们要确保在每一帧中，浏览器视口内的所有元素没有水平或垂直距离的移动。</p><p>这里有四种常见的优化建议。</p><h3 id="图片尺寸问题" tabindex="-1">图片尺寸问题 <a class="header-anchor" href="#图片尺寸问题" aria-label="Permalink to &quot;图片尺寸问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首先，我们需要确认浏览器视口中有多少图片，每张图片是否都已加上 width 和 height 属</span></span></code></pre></div><p>性。如果没有，是否会导致布局偏移？我们可以通过开发者工具来确认这个问题。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">以下代码为设置 width 和 height 属性的示例。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​img</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src=&quot;cls-of-image.jpg&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> width=&quot;400&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> height=&quot;160&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> class=&quot;cls&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> alt=&quot;cls-of-image&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">通过预设的 width 和 height 属性，浏览器就能提前在网页上分配空间，最大限度地减少重</span></span></code></pre></div><p>排和重新布局的可能。</p><p>但是，对于移动设备，预设的宽高无法适配那么多种屏幕大小和分辨率，那应如何解决呢？</p><p>第一种方法是设定宽高比。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CSS 属性 aspect-ratio 允许给盒子元素定义首选宽高比，它可以设定两个值，一个是</span></span></code></pre></div><p>auto，另一个是宽高比。如果为上述图片定义宽高比，参考代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.cls {</span></span>
<span class="line"><span> aspect-ratio: auto 400 / 160;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>对于未知尺寸的图片，我们可以通过宽高比告知浏览器分配页面空间。相对于未定义尺寸的图片，这种情况下的布局偏移会更小。不过，如果图片尺寸不同，加载后可能仍会出现布局偏移。</p><p>第二种方法是使用自适应图片特性。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>srcset 是 img 元素的新属性。它允许定义一个或多个图像候选地址，多地址之间以 , 分</span></span></code></pre></div><p>割。每张图片的候选地址包含图片 URL、可选宽度描述符和像素密度描述符。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>通过 srcset 属性，我们可以根据屏幕大小、分辨率去设置不同的图片格式，例如以下代</span></span></code></pre></div><p>码。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​img</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> width=&quot;64&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> height=&quot;64&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src=&quot;icon64px.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> srcset=&quot;icon32px.png 32w, icon64px.png 64w, icon-retina.png 2x icon-ultra.png 3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> alt=&quot;cls of icon image&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">除了 srcset 属性可以支持多种图片，HTML 还提供了 &lt;​picture&gt; 元素来解决不同屏幕大</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">小的响应式图片。它可以包含零或多个 &lt;​source&gt; 元素，以及一个 &lt;​img&gt; 元素来提供不同场</span></span></code></pre></div><p>景的图片地址。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果其他 &lt;​source&gt; 元素无法满足条件，那么就会使用 &lt;​img&gt; 元素作为默认提供的图片。</span></span></code></pre></div><p>下面是一个使用媒体查询特性在不同分辨率下应用不同格式图片的代码示例。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​picture&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;​source media=&quot;(max-width: 1024px)&quot; srcset=&quot;icon-retina.png 2x&quot; width=&quot;128&quot; hei</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;​source media=&quot;(min-width: 800px)&quot; srcset=&quot;icon64px.png 64w&quot; width=&quot;64&quot; height=</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;​img src=&quot;icon64px.png&quot; alt=&quot;cls of icon image&quot; width=&quot;64&quot; height=&quot;64&quot; /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​/picture&gt;</span></span></code></pre></div><p>总的来说，为了避免布局偏移问题，尤其是移动设备，我们应尽可能提前定义视口中的图片尺寸，即使我们无法预知这些尺寸，也可以设定一个预设的宽高比，以便浏览器预留空间渲染图片。</p><p>对于我们已知尺寸的图片，我们可以根据设备、屏幕大小、分辨率等因素，采用响应式的方法，预定义不同的图片大小和格式。只有这样，我们才能杜绝由于没有设置图片宽高而导致的布局偏移。</p><h3 id="动态内容" tabindex="-1">动态内容 <a class="header-anchor" href="#动态内容" aria-label="Permalink to &quot;动态内容&quot;">​</a></h3><p>网页中的图片通常是通过异步加载的方式获取的，除此之外，还有许多内容是通过异步加载的，如广告位、第三方插件代码、动态插入 DOM 内容等等。</p><p>像我们看到的加载更多商品的商品列表，或者实时更新信息流内容等，都可能导致页面结构的变化。</p><p>特别是动态插入的广告，通常会在页面主要内容生成后加载。如果此时页面没有为广告位预留空间，就可能导致布局偏移。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有的页面也会通过嵌入 iframe 来引入第三方内容，也很容易发生布局偏移。相关的参考代</span></span></code></pre></div><p>码如下。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​iframe</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src=&quot;//player.bilibili.com/player.html?isOutside=true</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">aid=1004606622</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bvid=BV1cx</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scrolling=&quot;no&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> border=&quot;0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> frameborder=&quot;no&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> framespacing=&quot;0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> allowfullscreen=&quot;true&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;​/iframe&gt;</span></span></code></pre></div><p>总的来说，动态插入页面内容是网页交互中最常见的行为。</p><p>想要避免由于动态内容导致的布局偏移，主要有四种方法。</p><p>首先，和优化图片加载基本相同，就是确保每个内容块都有预设的尺寸，或者通过宽高比来减少由于动态内容导致的布局偏移。</p><p>其次，避免在用户没有互动的情况下插入新内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第三，如果引入的是第三方代码，最好的方式是使用 div 包含它，并在这个 div 中预先定义</span></span>
<span class="line"><span>第三方页面内容的尺寸。但是，我们有时无法预知 iframe 内容是否符合预设的宽高。这就</span></span>
<span class="line"><span>需要我们在开发过程中多做多调试，确保 div 宽高和 iframe 内容的宽高保持一致。</span></span></code></pre></div><p>最后，相比于视口最高处位置，在页面视口靠下的位置动态插入内容，可以有效降低布局偏移的影响。</p><h3 id="动画问题" tabindex="-1">动画问题 <a class="header-anchor" href="#动画问题" aria-label="Permalink to &quot;动画问题&quot;">​</a></h3><p>CSS 动画可能是大部分前端同学最容易忽略的布局偏移问题。因为动画的复杂性和动态性可能掩盖了潜在的布局偏移问题。</p><p>例如，使用 CSS 动画改变元素位置时，因为浏览器必须重新计算元素位置，就可能会导致布局偏移。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为了避免这种情况，我们应该优先使用 transform 属性来改变元素的位置，而不是使用</span></span>
<span class="line"><span>top、right、bottom 或 left 属性。transform 属性不会导致布局偏移，因为它不会改</span></span></code></pre></div><p>变元素在文档流中的位置。</p><p>同样，如果我们在 CSS 动画中改变元素大小，也可能导致布局偏移。最佳做法是避免使用</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>width 和 height 属性改变元素的大小，而使用 transform: scale()。这样就不会改变</span></span></code></pre></div><p>元素在文档中的位置，也就不会导致布局偏移。</p><p>总的来说，我们应在网页的整个生命周期里，避免使用 CSS 改变元素的大小和位置，尽量使</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用 transform 属性替代。</span></span></code></pre></div><h3 id="字体问题" tabindex="-1">字体问题 <a class="header-anchor" href="#字体问题" aria-label="Permalink to &quot;字体问题&quot;">​</a></h3><p>我们在前面的章节提到，网络字体可能导致“无样式文本”闪烁问题，进而导致布局偏移。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解决这个问题的一种方法是预先设置 font-display 属性为 optional，这样，即使网络字</span></span></code></pre></div><p>体加载失败，浏览器也不会重新排版。</p><p>关于这方面的具体优化，我们在第 27 节课已经详细讲解过，这里就不再赘述。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>总结一下，累积布局偏移作为网页核心指标之一，其主要目的是衡量用户的真实交互体验。特别是在移动设备上，位置偏移和元素大小都可能导致布局偏移，页面内容在视口内的闪烁、跳动和移动，都可能让用户感到困扰。</p><p>只要 CLS 分数超过 0.1，我们就需要重点关注布局偏移问题，用开发者工具找出布局偏移的位置，然后分析可能存在的问题。</p><p>当然，页面交互过程中的布局偏移是无法避免的，我们需要根据实际情况分析具体问题，最核心的解决方案是视口内的所有元素，包括图片和视频，应提前设置宽高尺寸，以确保视口内容符合用户的预期。但但是，每个项目遇到的问题都不一样，如果真的无法避免某些布局偏移问题，我们应该考虑多种方案，让用户能感知即将发生的变化。同时，时刻关注 CLS 指标，通过开发者工具定位、排查布局偏移问题，找出有效的优化方案，让前端页面更友好，提升用户体验。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>现在，我给你布置一道思考题。</p><p>在你负责的前端项目中，尝试找出布局偏移的例子，并分析是否可以进行优化？如果是业务需要的布局偏移情况，你采取了哪些交互来解决用户体验问题？</p><p>欢迎你在留言区和我交流。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。我们下节课见！</p>`,106)])])}const g=a(n,[["render",p]]);export{d as __pageData,g as default};
